1	#!/usr/bin/env node
2	/**
3	 * BOUNDED FOOTING DIAGNOSTIC — run-local to 2026-09-05-after-the-hearth.
4	 *
5	 * Question, from root: why does the world's support query disagree with the
6	 * physically grounded body at the Origin audit site, where 200 shipped F
7	 * attempts at S were silently refused with `supported: false`?
8	 *
9	 * No voxel query is reachable from any read-only probe global, so this probe
10	 * discriminates between the remaining source candidates using ONLY the shipped
11	 * diagnostic and the shipped jump control:
12	 *
13	 *   `createFooting` (CommonGroundWorld.tsx) asks, for the grounded body pose,
14	 *   `cy = round((y - 1.05) / 2)`, then requires solid(cy), NOT solid(cy+1) and
15	 *   no water/hazard at cy or cy+1.
16	 *
17	 *   - If the body's standing cell is genuinely EMPTY in the terrain model, no
18	 *     height makes it supported.
19	 *   - If the cell ABOVE is logically solid (a generated/rendered or
20	 *     WorldSave/collider disagreement), then raising the feet by one cell makes
21	 *     the query land on that solid cell with air above it, and `supported`
22	 *     flips TRUE in mid-air. That is a decisive signature.
23	 *   - Water or hazard at the standing cell stays false at every height.
24	 *
25	 * It therefore samples `supported` as a FUNCTION OF THE BODY'S OWN HEIGHT while
26	 * the player jumps with the shipped Space control, and reports the observed
27	 * (feet height -> voxel cell -> supported) map with the cell arithmetic made
28	 * explicit. It grants nothing: a jump is an ordinary player action, no story
29	 * state is written, no predicate is touched and no ground is invented.
30	 *
31	 * Root control is polled every --control-ms (default 10 s) exactly as the
32	 * journey probe does, and a checkpoint finalises the media and summary.
33	 *
34	 *   node cg-footing-diag.mjs --beat ch13-survey --seconds 150 --out final/footing-diag
35	 */
36	import { mkdirSync, writeFileSync, appendFileSync, readFileSync } from 'node:fs';
37	import { resolve, join } from 'node:path';
38	import { createHash } from 'node:crypto';
39	import process from 'node:process';
40	import { loadContract, ART, CAPTURES, RUN_DIR } from './lib/cgContract.mjs';
41	import { openParavoxia, waitReady, readState, frameStats } from '../../../../../main/tools/lib/evidence.mjs';
42	
43	const arg = (n, d = null) => {
44	  const i = process.argv.indexOf(`--${n}`);
45	  return i >= 0 && process.argv[i + 1] !== undefined && !process.argv[i + 1].startsWith('--') ? process.argv[i + 1] : d;
46	};
47	const has = (n) => process.argv.includes(`--${n}`);
48	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
49	const tag = (m) => console.log(`[cg-footing] ${m}`);
50	
51	const VOXEL_SCALE = 2;          // src/utils/cubeGravityConstants.ts
52	const GROUND_CLEARANCE = 1.05;  // src/story/world/CommonGroundWorld.tsx
53	const cell = (v) => Math.round(v / VOXEL_SCALE);
54	
55	// -------------------------------------------------------------- self-test ---
56	if (has('self-test')) {
57	  const fail = (m) => { console.error(`[cg-footing self-test] FAIL ${m}`); process.exit(1); };
58	  // The exact arithmetic the chapter uses, checked against the two heights this
59	  // run actually observed and against the authored pose.
60	  if (cell(50.988975 - GROUND_CLEARANCE) !== 25) fail('observed audit-site feet must map to cell 25');
61	  if (cell(51.05 - GROUND_CLEARANCE) !== 25) fail('the AUTHORED pose must map to the same cell 25');
62	  if (cell(51.186 - GROUND_CLEARANCE) !== 25) fail('the supported landing-site height also maps to cell 25');
63	  // one cell up: feet above 52.05 land the query on cell 26
64	  if (cell(52.10 - GROUND_CLEARANCE) !== 26) fail('a one-cell lift must query cell 26');
65	  if (cell(53.99 - GROUND_CLEARANCE) !== 26) fail('cell 26 must span to just under 54.05');
66	  // and the classifier
67	  const c = (rows) => classify(rows);
68	  if (c([{ cy: 25, supported: false }, { cy: 26, supported: true }]) !== 'supported-only-one-cell-above-the-standing-cell') fail('lift-true signature');
69	  if (c([{ cy: 25, supported: false }, { cy: 26, supported: false }]) !== 'unsupported-at-every-sampled-height') fail('all-false signature');
70	  if (c([{ cy: 25, supported: true }]) !== 'supported-at-the-standing-cell') fail('normal signature');
71	  if (c([]) !== 'insufficient-samples') fail('empty signature');
72	  console.log('[cg-footing self-test] OK — cell arithmetic and the three signatures');
73	  process.exit(0);
74	}
75	
76	function classify(rows) {
77	  if (!rows.length) return 'insufficient-samples';
78	  const standing = Math.min(...rows.map((r) => r.cy));
79	  const atStanding = rows.filter((r) => r.cy === standing);
80	  const above = rows.filter((r) => r.cy > standing);
81	  if (atStanding.some((r) => r.supported === true)) return 'supported-at-the-standing-cell';
82	  if (above.length && above.some((r) => r.supported === true)) return 'supported-only-one-cell-above-the-standing-cell';
83	  return 'unsupported-at-every-sampled-height';
84	}
85	
86	const beat = arg('beat', 'ch13-survey');
87	const seconds = Number(arg('seconds', '150'));
88	const outName = arg('out', 'final/footing-diag');
89	const controlMs = Number(arg('control-ms', '10000'));
90	const sampleMs = Number(arg('sample-ms', '50'));
91	const jumps = Number(arg('jumps', '10'));
92	const approachUnits = Number(arg('approach-units', '2.5'));
93	
94	const ownership = JSON.parse(readFileSync(resolve(ART, 'preview-ownership.json'), 'utf8'));
95	if (ownership.state !== 'running') throw new Error(`owned preview is "${ownership.state}", not running — refusing to measure or to start one`);
96	const { sha256: contractSha } = loadContract();
97	const CONTROL_PATH = resolve(RUN_DIR, 'verifier-control.json');
98	const CHECKPOINT = new Set(['finish-current-and-checkpoint', 'pause', 'stop', 'halt']);
99	
100	const outDir = resolve(CAPTURES, outName);
101	mkdirSync(outDir, { recursive: true });
102	const tracePath = join(outDir, 'trace.ndjson');
103	writeFileSync(tracePath, '');
104	
105	const S = [-26, 51.05, 12];
106	const url = `?story=${beat}&journeyprobe=1&debug=1&movie=1`;
107	tag(`beat=${beat} url=${ownership.url}${url}`);
108	
109	let control = null;
110	const pollControl = () => {
111	  try {
112	    const live = JSON.parse(readFileSync(CONTROL_PATH, 'utf8'));
113	    if (CHECKPOINT.has(String(live.action))) control = live;
114	    return live;
115	  } catch { return null; }
116	};
117	if (pollControl()) { /* recorded below */ }
118	if (control) {
