        const rec = { hook: h.member ? `window.${h.global}.${h.member}()` : `window.${h.global}()`, present: false, called: false, error: null };
        try {
          const root = window[h.global];
          const fn = h.member ? root?.[h.member] : root;
          rec.present = typeof fn === 'function';
          if (rec.present) {
