await check('A8 the guard touches ONLY the session it owns — never the preview or the browser', async () => {
  const s = stubSession();
  const guard = createOwnedSessionGuard();
  guard.adopt(s);
  try { await guard.runGuarded(async () => { throw new Error('x'); }); } catch { /* expected */ }
